{"content": "     1|import express from "express";
     2|import helmet from "helmet";
     3|import { createServer as createViteServer } from "vite";
     4|import sqlite3 from "sqlite3";
     5|import { open } from "sqlite";
     6|import cors from "cors";
     7|import bcrypt from "bcrypt";
     8|
     9|async function startServer() {
    10|  const app = express();
    11|  const PORT = parseInt(process.env.PORT || "3000", 10);
    12|
    13|  app.use(cors());
    14|  app.use(express.json({ limit: "50mb" }));
    15|  app.use(helmet());
    16|
    17|  // Setup SQLite
    18|  const db = await open({
    19|    filename: "./database.sqlite",
    20|    driver: sqlite3.Database,
    21|  });
    22|
    23|  await db.exec(`
    24|    CREATE TABLE IF NOT EXISTS projects (
    25|      id TEXT PRIMARY KEY,
    26|      ownerId TEXT,
    27|      data TEXT
    28|    );
    29|    CREATE TABLE IF NOT EXISTS users (
    30|      id TEXT PRIMARY KEY,
    31|      username TEXT,
    32|      email TEXT UNIQUE,
    33|      password TEXT,
    34|      geminiKey TEXT
    35|    );
    36|  `);
    37|
    38|  try {
    39|    await db.exec(`ALTER TABLE users ADD COLUMN geminiKey TEXT;`);
    40|  } catch (e: any) {
    41|    // Ignore error if column already exists
    42|  }
    43|
    44|  // Auth Routes
    45|  app.post("/api/auth/signup", async (req, res) => {
    46|    const { username, email, password, geminiKey } = req.body;
    47|    if (!username || !email || !password) {
    48|      return res.status(400).json({ error: "Missing required fields" });
    49|    }
    50|    try {
    51|      const id = `user-${Date.now()}`;
    52|      const hashedPassword = await bcrypt.hash(password, 10);
    53|      await db.run(
    54|        "INSERT INTO users (id, username, email, password, geminiKey) VALUES (?, ?, ?, ?, ?)",
    55|        [id, username, email, hashedPassword, geminiKey || null]
    56|      );
    57|      res.json({ id, username, email, geminiKey: geminiKey || null, notificationPrefs: {} });
    58|    } catch (error: any) {
    59|      if (error.message.includes("UNIQUE constraint failed")) {
    60|        return res.status(409).json({ error: "Email already exists" });
    61|      }
    62|      console.error("Signup error:", error);
    63|      res.status(500).json({ error: "Failed to create user" });
    64|    }
    65|  });
    66|
    67|  app.post("/api/auth/login", async (req, res) => {
    68|    const { email, password } = req.body;
    69|    if (!email || !password) {
    70|      return res.status(400).json({ error: "Missing email/username or password" });
    71|    }
    72|    try {
    73|      const user = await db.get(
    74|        "SELECT id, username, email, password as hashedPassword, geminiKey FROM users WHERE email = ? OR username = ?",
    75|        [email, email]
    76|      );
    77|      
    78|      if (user && await bcrypt.compare(password, user.hashedPassword)) {
    79|        const { hashedPassword, ...userWithoutPassword } = user;
    80|        res.json({ ...userWithoutPassword, notificationPrefs: {} });
    81|      } else {
    82|        res.status(401).json({ error: "Invalid credentials" });
    83|      }
    84|    } catch (error) {
    85|      console.error("Login error:", error);
    86|      res.status(500).json({ error: "Failed to login" });
    87|    }
    88|  });
    89|
    90|  app.post("/api/users/:id/geminikey", async (req, res) => {
    91|    const { id } = req.params;
    92|    const { geminiKey } = req.body;
    93|    try {
    94|      await db.run("UPDATE users SET geminiKey = ? WHERE id = ?", [geminiKey, id]);
    95|      res.json({ success: true });
    96|    } catch (error) {
    97|      console.error("Failed to update Gemini key:", error);
    98|      res.status(500).json({ error: "Failed to update Gemini key" });
    99|    }
   100|  });
   101|
   102|  // API Routes
   103|  app.get("/api/projects", async (req, res) => {
   104|    const { userId } = req.query;
   105|    try {
   106|      let rows;
   107|      if (userId) {
   108|        rows = await db.all("SELECT data FROM projects WHERE ownerId = ?", [userId]);
   109|      } else {
   110|        rows = await db.all("SELECT data FROM projects");
   111|      }
   112|      const projects = rows.map((row) => JSON.parse(row.data));
   113|      res.json(projects);
   114|    } catch (error) {
   115|      console.error("Failed to fetch projects:", error);
   116|      res.status(500).json({ error: "Failed to fetch projects" });
   117|    }
   118|  });
   119|
   120|  app.post("/api/projects", async (req, res) => {
   121|    try {
   122|      const projects = req.body; // Expecting an array of projects to sync
   123|      if (!Array.isArray(projects)) {
   124|        return res.status(400).json({ error: "Expected an array of projects" });
   125|      }
   126|      for (const project of projects) {
   127|        await db.run(
   128|          "INSERT OR REPLACE INTO projects (id, ownerId, data) VALUES (?, ?, ?)",
   129|          [project.id, project.ownerId, JSON.stringify(project)]
   130|        );
   131|      }
   132|      res.json({ success: true });
   133|    } catch (error) {
   134|      console.error("Failed to save projects:", error);
   135|      res.status(500).json({ error: "Failed to save projects" });
   136|    }
   137|  });
   138|
   139|  app.delete("/api/projects/:id", async (req, res) => {
   140|    const { id } = req.params;
   141|    try {
   142|      await db.run("DELETE FROM projects WHERE id = ?", [id]);
   143|      res.json({ success: true });
   144|    } catch (error) {
   145|      console.error("Failed to delete project:", error);
   146|      res.status(500).json({ error: "Failed to delete project" });
   147|    }
   148|  });
   149|
   150|  app.delete("/api/projects", async (req, res) => {
   151|    const { userId } = req.query;
   152|    try {
   153|      if (userId) {
   154|        await db.run("DELETE FROM projects WHERE ownerId = ?", [userId]);
   155|      } else {
   156|        await db.run("DELETE FROM projects");
   157|      }
   158|      res.json({ success: true });
   159|    } catch (error) {
   160|      console.error("Failed to delete projects:", error);
   161|      res.status(500).json({ error: "Failed to delete projects" });
   162|    }
   163|  });
   164|
   165|  // Vite middleware for development
   166|  console.log(`NODE_ENV: ${process.env.NODE_ENV}`);
   167|  if (process.env.NODE_ENV !== "production") {
   168|    console.log("Starting Vite in middleware mode...");
   169|    const vite = await createViteServer({
   170|      server: { middlewareMode: true },
   171|      appType: "spa",
   172|    });
   173|    app.use(vite.middlewares);
   174|  } else {
   175|    console.log("Serving static files from dist...");
   176|    app.use(express.static("dist"));
   177|  }
   178|
   179|  app.listen(PORT, "0.0.0.0", () => {
   180|    console.log(`Server running on http://localhost:${PORT}`);
   181|  });
   182|}
   183|
   184|startServer();
   185|", "total_lines": 184, "file_size": 5825, "truncated": false, "is_binary": false, "is_image": false}

