                            {suggestedSetup && (
                                <div style={{
                                    padding: '0.75rem 1rem', borderRadius: 'var(--radius-sm)',
                                    background: 'rgba(16, 185, 129, 0.1)', border: '1px solid rgba(16, 185, 129, 0.3)',
